// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let n, m, k;
let s;
let l = 60;

Grid[][] grids;

function setup() {
  createCanvas(2400, 2400);
  noFill();
  noLoop();
  init();
}

function init() {
  //n = int(random(4, 8));
  n = 4;
  m = 4; // m > n
  s = (width-2*l)/m;
  grids = new Array(n)[m];
  k = 0;
  let mult = 1;
  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      grids[i][j] = new Grid(l+i*s, l+j*s, s*mult);
    }
  }
}

function draw() {
  background("#db3a34");
  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      grids[i][j].display(i, j);
    }
  }
}

class Grid {
  x, y, d, r, t;

  constructor(tx, ty, tsz) {
    x = tx;
    y = ty;
    d = tsz;
    r = d/2;
  }

  function display(p, q) {
    pushMatrix();
    translate(x+d/2, y+d/2);
    noStroke();
    fill(0);
    ellipse(0, 0, d, d);

    t = PI*random(2);
    let p1 = new PVector(r*cos(t), r*sin(t));

    stroke("#db3a34");
    //for (i = 0; i < (p+1)*2; i++) {
    //for (i = 0; i < (p+1)*(q+1); i++) {
    //for (i = 0; i < p*n+q+1; i++) {
    for (i = 0; i < 150; i++) {
      //t = random(2*(p+1)*PI/n);
      strokeWeight(random(0.5, 2));
      t = PI*random(2);
      line(p1.x, p1. y, r*cos(t), r*sin(t));
      p1.x = r*cos(t);
      p1.y = r*sin(t);
    }
    popMatrix();
  }
}

function mouseReleased() {
  init();
  redraw();
}

